// Aplana la respuesta JSON-RPC de raffle.ticket.summary (campos many2one
// vienen como [id, display_name]) y junta los partner_id unicos para la
// siguiente llamada (necesitamos res.partner.phone, que NO esta en la vista SQL).

const response = $input.first().json;
const rows = (response && response.result) || [];

const summaries = rows.map((row) => ({
  partner_id: Array.isArray(row.partner_id) ? row.partner_id[0] : row.partner_id,
  partner_name: Array.isArray(row.partner_id) ? row.partner_id[1] : '',
  campaign_id: Array.isArray(row.campaign_id) ? row.campaign_id[0] : row.campaign_id,
  campaign_name: Array.isArray(row.campaign_id) ? row.campaign_id[1] : '',
  ticket_count: row.ticket_count,
  physical_count: row.physical_count,
  online_count: row.online_count,
  folios: String(row.legacy_refs || '')
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean),
}));

const partnerIds = [...new Set(summaries.map((s) => s.partner_id).filter(Boolean))];

return [{
  json: {
    summaries,
    partner_ids: partnerIds,
  },
}];

// Une el resumen (folios/conteos) con el telefono real de cada cliente y
// arma un item por cada (partner, campaign) listo para el loop de envio.

const summaries = $('Extraer IDs de Clientes y Aplanar Resumen').first().json.summaries;
const partnersResp = $input.first().json;
const partners = (partnersResp && partnersResp.result) || [];

const phoneById = {};
for (const p of partners) {
  phoneById[p.id] = String(p.phone || '').replace(/[\s-]/g, '');
}

// URL del portal (ya construido en este proyecto: /my/raffles). Configurable
// por ambiente via variable de entorno PORTAL_BASE_URL.
const portalBaseUrl = $env.PORTAL_BASE_URL || 'https://portal.medicinedepot.mx';

return summaries.map((s) => {
  const phone = phoneById[s.partner_id] || '';
  const hasValidPhone = /^\+[1-9]\d{7,14}$/.test(phone);
  return {
    json: {
      to: phone,
      has_valid_phone: hasValidPhone,
      partner_id: s.partner_id,
      partner_name: s.partner_name,
      campaign_id: s.campaign_id,
      campaign_name: s.campaign_name,
      ticket_count: s.ticket_count,
      folios_count: s.folios.length,
      portal_url: `${portalBaseUrl}/my/raffles`,
    },
  };
});
